-- CRM 单元测试表结构（H2 内存库）
-- 说明：只建「单测用到的表」，字段与 deploy/mysql/init 中的 crm 表保持一致；
--      注意 tenant_id 必须存在，因为单测里会注册多租户拦截器（TenantLineInnerInterceptor），
--      所有 SQL 都会自动拼接 tenant_id 条件。

CREATE TABLE IF NOT EXISTS "crm_customer" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255) NOT NULL,
    "follow_up_status" bit DEFAULT FALSE,
    "contact_last_time" timestamp DEFAULT NULL,
    "contact_last_content" varchar(512) DEFAULT NULL,
    "contact_next_time" timestamp DEFAULT NULL,
    "owner_user_id" bigint DEFAULT NULL,
    "owner_time" timestamp DEFAULT NULL,
    "lock_status" bit DEFAULT FALSE,
    "deal_status" bit DEFAULT FALSE,
    "mobile" varchar(20) DEFAULT NULL,
    "telephone" varchar(20) DEFAULT NULL,
    "qq" varchar(20) DEFAULT NULL,
    "wechat" varchar(32) DEFAULT NULL,
    "email" varchar(64) DEFAULT NULL,
    "area_id" int DEFAULT NULL,
    "detail_address" varchar(255) DEFAULT NULL,
    "industry_id" int DEFAULT NULL,
    "level" int DEFAULT NULL,
    "source" int DEFAULT NULL,
    "customer_type" int DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CRM 客户';

CREATE TABLE IF NOT EXISTS "crm_follow_up_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "biz_type" int DEFAULT NULL,
    "biz_id" bigint DEFAULT NULL,
    "type" int DEFAULT NULL,
    "content" varchar(512) DEFAULT '',
    "next_time" timestamp DEFAULT NULL,
    "follow_up_time" timestamp DEFAULT NULL,
    "pic_urls" varchar(1024) DEFAULT NULL,
    "file_urls" varchar(1024) DEFAULT NULL,
    "business_ids" varchar(255) DEFAULT '',
    "contact_ids" varchar(255) DEFAULT '',
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CRM 跟进记录';

CREATE TABLE IF NOT EXISTS "crm_customer_pool_config" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "enabled" bit DEFAULT FALSE,
    "contact_expire_days" int DEFAULT NULL,
    "deal_expire_days" int DEFAULT NULL,
    "notify_enabled" bit DEFAULT FALSE,
    "notify_days" int DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'CRM 客户公海配置';
